'use client';

import { useCallback, useDeferredValue, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Building2, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, Cloud, Database, Download, ExternalLink, FileDown, FileSpreadsheet, FolderOpen, HardDrive, Info, Layers3, LayoutDashboard, LoaderCircle, Menu, Package, RefreshCw, Search, ShieldCheck, SlidersHorizontal, TriangleAlert, Upload, Users, Wallet, X } from 'lucide-react';
import Members from './members';
import type { Identity } from '@/lib/access';
import { confirmedCatalog, groupPurchases, itemDestination, purchasePageUrl, type PurchaseInfo } from '@/lib/purchases';
import { EMPTY_FILTERS, HEADERS, METHODOLOGY, ataKey, clampPercent, dateLabel, fileLinks, filterEntries, groupEntries, money, normalize, number, parseUpload, percent, purchaseKey, safeUrl, todayBR, toEntries, totalize, type BalanceStatus, type Dataset, type Entry, type Filters, type Group } from '@/lib/arp';

type View = 'overview' | 'purchases' | 'atas' | 'suppliers' | 'source';
const LOCAL_KEY = 'arp-executivo-local-v1';
const PAGE_SIZE = 12;
const statusClass: Record<BalanceStatus, string> = { Normal:'normal', Crítico:'critical', Esgotado:'empty', Revisar:'review' };

function AcantoMark({ className = '' }: { className?:string }) {
  return <img className={`acanto-mark ${className}`} src="/intendencia-acanto.svg" alt="" aria-hidden="true" width={178} height={93}/>;
}

function Checkbox({ checked, mixed = false, label, onChange }: { checked: boolean; mixed?: boolean; label: string; onChange: () => void }) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => { if (ref.current) ref.current.indeterminate = mixed && !checked; }, [mixed, checked]);
  return <input ref={ref} type="checkbox" className="check" checked={checked} onChange={onChange} aria-label={label} />;
}
function Status({ value }: { value: BalanceStatus }) { return <span className={`status ${statusClass[value]}`}><i />{value}</span>; }
function Progress({ value, status = 'Normal' }: { value: number | null; status?: BalanceStatus }) {
  return <div className={`progress ${statusClass[status]}`} role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value === null ? undefined : clampPercent(value)} aria-label="Consumo calculado" title={`Consumo calculado: ${percent(value)}`}><span style={{ width: `${clampPercent(value)}%` }} /></div>;
}
function LinkButton({ url, children }: { url: string; children: ReactNode }) {
  const href = safeUrl(url);
  return href ? <a href={href} target="_blank" rel="noopener noreferrer" className="link-button">{children}<ArrowUpRight size={12}/></a> : <span className="muted text-xs">Link não informado</span>;
}
function Select({ label, value, onChange, options, all = 'Todos', emphasis = false }: { emphasis?:boolean; label: string; value: string; onChange: (v: string) => void; options: [string, string][]; all?: string }) {
  return <label className={`filter-label ${emphasis?'available-filter':''}`}><span>{label}</span><div className="select-wrap"><select value={value} onChange={e => onChange(e.target.value)} title={options.find(([key]) => key === value)?.[1] ?? all}><option value="">{all}</option>{options.map(([key, text]) => <option key={key} value={key}>{text}</option>)}</select><ChevronDown size={14}/></div></label>;
}
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLDialogElement>(null);
  useEffect(() => { dialog.current?.showModal(); const previous = document.body.style.overflow; document.body.style.overflow = 'hidden'; return () => { document.body.style.overflow = previous; }; }, []);
  return <dialog ref={dialog} className={`modal ${wide ? 'wide' : ''}`} onCancel={onClose} onClick={e => { if (e.target === e.currentTarget) onClose(); }}><div className="modal-top"><div className="min-w-0"><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Fechar janela"><X size={20}/></button></div><div className="modal-body">{children}</div></dialog>;
}
function ItemDetail({ entry, onClose }: { entry: Entry; onClose: () => void }) {
  return <Modal title={`Item ${entry.raw['Nº ITEM']} · Ata ${entry.raw['Nº ATA']}/${entry.raw['ANO ATA']}`} subtitle={`Linha ${entry.line} da planilha original`} onClose={onClose} wide><p className="detail-description">{entry.raw.DESCRIÇÃO}</p><div className="detail-metrics"><div><span>Total homologado</span><strong>{money(entry.approvedValue)}</strong></div><div><span>Consumo calculado</span><strong>{money(entry.usedValue)}</strong></div><div><span>Saldo disponível</span><strong className="accent">{money(entry.availableValue)}</strong></div></div>{entry.warning && <div className="notice warning"><TriangleAlert size={18}/>{entry.warning}</div>}<p className="method-note">{METHODOLOGY}</p><dl className="raw-grid">{HEADERS.map(h => <div key={h}><dt>{h}</dt><dd>{entry.raw[h] || 'Não informado'}</dd></div>)}</dl><div className="flex flex-wrap gap-2 mt-6"><LinkButton url={entry.raw['LINK ATA PNCP']}>Ata no PNCP</LinkButton><LinkButton url={entry.raw['LINK COMPRA PNCP']}>Compra no PNCP</LinkButton><LinkButton url={itemDestination(entry.raw).url}>{itemDestination(entry.raw).label}</LinkButton>{itemDestination(entry.raw).legacy&&<p className="method-note">O link antigo da planilha está indisponível. Abra a compra no PNCP e localize o item {entry.raw['Nº ITEM']}. O endereço original permanece registrado acima.</p>}{fileLinks(entry.raw.ARQUIVOS).map((url, i) => <LinkButton key={url} url={url}>Arquivo {i+1}</LinkButton>)}</div></Modal>;
}
function AtaCard({ group, selected, toggleItems, onDetail, open, onToggle }: { group: Group; selected: Set<string>; toggleItems: (items: Entry[]) => void; onDetail: (entry: Entry) => void; open: boolean; onToggle: () => void }) {
  const [itemPage, setItemPage] = useState(0);
  const t = group.totals, r = group.raw;
  const count = group.entries.filter(e => selected.has(e.id)).length;
  const overall: BalanceStatus = t.invalid ? 'Revisar' : t.availableValue.isZero() ? 'Esgotado' : t.approvedValue.gt(0) && t.availableValue.div(t.approvedValue).lt('.15') ? 'Crítico' : 'Normal';
  const endDates = [...new Set(group.entries.map(e => e.ends).filter(Boolean))].sort();
  const end = endDates.at(0) ?? null;
  const expired = end && end < todayBR();
  const visible = group.entries.slice(itemPage*20,(itemPage+1)*20);
  return <article className={`ata-card ${open ? 'is-open' : ''}`}><div className="ata-heading"><Checkbox checked={count === group.entries.length} mixed={count > 0} label={`Selecionar ata ${r['Nº ATA']}/${r['ANO ATA']} · ${r['NOME UGG']}`} onChange={() => toggleItems(group.entries)}/><button className="ata-expand" aria-expanded={open} onClick={onToggle}><div className="ata-symbol"><FolderOpen size={21}/></div><div className="ata-identity"><div className="flex flex-wrap items-center gap-x-3 gap-y-1"><h3>Ata {r['Nº ATA']}<span> / {r['ANO ATA']}</span></h3><span className="small-pill">{r.MODALIDADE} {r['Nº COMPRA']}/{r['ANO COMPRA']}</span></div><p title={`${r.UGG} · ${r['NOME UGG']}`}><Building2 size={12}/>{r['NOME UGG']}<span className="muted">· UGG {r.UGG}</span><span className="muted">· {group.entries.length} {group.entries.length === 1 ? 'item' : 'itens'}</span></p></div><ChevronDown className={`ata-chevron ${open ? 'rotate-180' : ''}`} size={18}/></button><div className="ata-balance"><span>Disponível</span><strong title={money(t.availableValue)}>{money(t.availableValue)}</strong></div><div className="ata-progress"><div className="flex justify-between gap-3"><span>Consumo financeiro</span><strong>{percent(t.financialPercent)}</strong></div><Progress value={t.financialPercent} status={overall}/></div><div className="ata-status"><Status value={overall}/>{expired && <span className="expiry">Vencida</span>}</div></div>{open && <div className="ata-content"><div className="ata-summary"><div><span>Homologado</span><strong>{money(t.approvedValue)}</strong></div><div><span>Consumo calculado</span><strong>{money(t.usedValue)}</strong></div><div><span>Vigência final{endDates.length>1?' mais próxima':''}</span><strong className={expired?'text-amber-300':''}>{dateLabel(end)}</strong></div><div className="flex flex-wrap gap-2"><LinkButton url={r['LINK ATA PNCP']}>Ata PNCP</LinkButton><LinkButton url={r['LINK COMPRA PNCP']}>Compra PNCP</LinkButton></div></div><div className="table-scroll"><table className="items-table"><thead><tr><th className="w-12"><span className="sr-only">Seleção</span></th><th>Item / descrição</th><th>Fornecedor</th><th className="text-right">Valor unitário</th><th className="text-right">Homologada</th><th className="text-right">Registrada</th><th className="text-right available-column">Qtd. disponível</th><th>Consumo calculado</th><th className="text-right">Saldo em R$</th><th>Ações</th></tr></thead><tbody>{visible.map(e => <tr key={e.id} className={selected.has(e.id)?'selected-row':''}><td><Checkbox checked={selected.has(e.id)} label={`Selecionar item ${e.raw['Nº ITEM']} da ata ${e.raw['Nº ATA']}`} onChange={() => toggleItems([e])}/></td><td><button className="item-name" onClick={() => onDetail(e)}><span className="item-code">#{e.raw['Nº ITEM']}<span> · {e.raw['CÓD ITEM']}</span></span><span title={e.raw.DESCRIÇÃO} className="line-clamp-2">{e.raw.DESCRIÇÃO}</span></button></td><td><span className="supplier-name" title={e.raw['NOME CNPJ']}>{e.raw['NOME CNPJ']}</span><span className="item-code">{e.raw.CNPJ}</span></td><td className="numeric" title={e.raw['VALOR UNITÁRIO']}>{money(e.price)}</td><td className="numeric">{number(e.approved)}</td><td className="numeric">{e.registered===null?'—':number(e.registered)}</td><td className="numeric available-column"><strong className={`available-quantity ${e.available.isZero()?'is-empty':''}`}>{number(e.available)}</strong></td><td><div className="item-consumption"><span>{percent(e.usedPercent)}</span><Status value={e.status}/></div><Progress value={e.usedPercent} status={e.status}/></td><td className="numeric accent">{money(e.availableValue)}</td><td><div className="item-actions"><button className="icon-button" onClick={() => onDetail(e)} title="Ver as 26 colunas e todos os links" aria-label={`Detalhar item ${e.raw['Nº ITEM']}`}><Search size={15}/></button><LinkButton url={itemDestination(e.raw).url}>{itemDestination(e.raw).label}</LinkButton>{fileLinks(e.raw.ARQUIVOS).slice(0,1).map(url=><LinkButton key={url} url={url}>Arquivo</LinkButton>)}</div></td></tr>)}</tbody></table></div>{group.entries.length>20 && <div className="pagination"><span>{itemPage*20+1}–{Math.min((itemPage+1)*20,group.entries.length)} de {group.entries.length} itens</span><div><button className="icon-button" disabled={itemPage===0} onClick={()=>setItemPage(p=>p-1)} aria-label="Itens anteriores"><ArrowLeft size={16}/></button><button className="icon-button" disabled={(itemPage+1)*20>=group.entries.length} onClick={()=>setItemPage(p=>p+1)} aria-label="Próximos itens"><ArrowRight size={16}/></button></div></div>}<p className="ata-footnote"><Info size={13}/>Consumo por item = homologada − disponível. Clique na descrição para consultar todas as colunas e arquivos.</p></div>}</article>;
}


function PurchaseCard({ purchase, selected, toggleItems, onDetail, expanded, toggleAta }: {purchase:ReturnType<typeof groupPurchases>[number];selected:Set<string>;toggleItems:(items:Entry[])=>void;onDetail:(e:Entry)=>void;expanded:Set<string>;toggleAta:(key:string)=>void}){
 const [open,setOpen]=useState(false),[info,setInfo]=useState<PurchaseInfo|null>(()=>confirmedCatalog[purchase.key]??null),[loading,setLoading]=useState(false),[message,setMessage]=useState('');
 const r=purchase.raw,t=purchase.totals;
 useEffect(()=>{if(!open||(info&&Date.now()-Date.parse(info.checkedAt)<24*3600*1000))return;setLoading(true);const controller=new AbortController();const query=new URLSearchParams({link:r['LINK COMPRA PNCP'],ugg:r.UGG,number:r['Nº COMPRA'],year:r['ANO COMPRA']});fetch(`/api/purchase?${query}`,{signal:controller.signal}).then(async response=>{const b=await response.json();if(!response.ok)throw new Error(b.error);setInfo(b);}).catch(e=>{if(e.name!=='AbortError')setMessage(e.message);}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[open,r]);
 const count=purchase.entries.filter(e=>selected.has(e.id)).length;
 return <article className="purchase-card"><div className="purchase-heading"><Checkbox checked={count===purchase.entries.length} mixed={count>0} label={`Selecionar pregão ${r['Nº COMPRA']}/${r['ANO COMPRA']} UGG ${r.UGG}`} onChange={()=>toggleItems(purchase.entries)}/><button className="purchase-toggle" onClick={()=>setOpen(v=>!v)} aria-expanded={open}><div><span className="eyebrow">UGG {r.UGG} · {r['NOME UGG']}</span><h3>{r.MODALIDADE} {r['Nº COMPRA']}/{r['ANO COMPRA']}</h3><span className="muted">{purchase.atas.length} atas · {purchase.entries.length} itens no filtro</span></div><ChevronDown className={open?'rotate-180':''}/></button><div className="purchase-value"><span>Saldo disponível</span><strong>{money(t.availableValue)}</strong></div></div><div className="purchase-object"><strong>Objeto do pregão</strong><p>{loading?'Consultando o PNCP…':info?.object||message||info?.error||'Abra a seta do pregão para consultar o objeto no PNCP.'}</p><div className="purchase-source"><LinkButton url={purchasePageUrl(r)}>Consultar PNCP</LinkButton>{info?.originUrl&&<LinkButton url={info.originUrl}>Compra no Compras.gov</LinkButton>}{info?.verified&&<small>Fonte: PNCP · consultado em {new Date(info.checkedAt).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small>}</div></div><div className="purchase-finance"><span>Homologado <b>{money(t.approvedValue)}</b></span><span>Consumo calculado <b>{money(t.usedValue)}</b></span><span>Consumo financeiro <b>{percent(t.financialPercent)}</b></span></div><Progress value={t.financialPercent}/>{open&&<div className="purchase-atas">{purchase.atas.map(group=><AtaCard key={group.key} group={group} selected={selected} toggleItems={toggleItems} onDetail={onDetail} open={expanded.has(group.key)} onToggle={()=>toggleAta(group.key)}/>)}</div>}</article>;
}

export default function Dashboard({identity,onLogout}:{identity:Identity;onLogout:()=>void}) {
  const canManage=identity.role==='admin';
  const [helpOpen,setHelpOpen]=useState(false);
  const [helpStep,setHelpStep]=useState(0);
  const [dataset, setDataset] = useState<Dataset | null>(null);
  const [version,setVersion] = useState(0);
  const [storage,setStorage] = useState<'supabase'|'local'>('local');
  const [loading,setLoading] = useState(true);
  const [error,setError] = useState('');
  const [toast,setToast] = useState('');
  const [view,setView] = useState<View>('overview');
  const [mobileNav,setMobileNav] = useState(false);
  const [filters,setFilters] = useState<Filters>(EMPTY_FILTERS);
  const [advanced,setAdvanced] = useState(false);
  const [selected,setSelected] = useState<Set<string>>(new Set());
  const [expanded,setExpanded] = useState<Set<string>>(new Set());
  const [page,setPage] = useState(0);
  const [sort,setSort] = useState('available-desc');
  const [detail,setDetail] = useState<Entry | null>(null);
  const [methodOpen,setMethodOpen] = useState(false);
  const [importOpen,setImportOpen] = useState(false);
  const [pending,setPending] = useState<Dataset | null>(null);
  const [busy,setBusy] = useState('');
  const [drag,setDrag] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const deferredQuery = useDeferredValue(filters.query);

  const load = useCallback(async (preferLocal = true) => {
    setLoading(true);setError('');
    try {
      if(preferLocal&&canManage){const stored=localStorage.getItem(LOCAL_KEY);if(stored){const local=JSON.parse(stored);toEntries(local.dataset);setDataset(local.dataset);setVersion(local.version ?? 0);setStorage('local');setSelected(new Set());return;}}
      const response=await fetch('/api/dataset',{cache:'no-store'});const body=await response.json();
      if(!response.ok)throw new Error(body.error ?? 'Falha ao carregar a base.');
      toEntries(body.dataset);setDataset(body.dataset);setVersion(body.version);setStorage(body.storage);setSelected(new Set());if(body.warning)setError(body.warning);
    }catch(e){setError(e instanceof Error?e.message:'Falha ao carregar.');}finally{setLoading(false);}
  },[canManage]);
  useEffect(()=>{void load();},[load]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5500);return()=>clearTimeout(timer);},[toast]);
  useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchRef.current?.focus();}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[]);
  const entries=useMemo(()=>dataset?toEntries(dataset):[],[dataset]);
  const filtered=useMemo(()=>filterEntries(entries,{...filters,query:deferredQuery}),[entries,filters,deferredQuery]);
  const totals=useMemo(()=>totalize(filtered),[filtered]);
  const groups=useMemo(()=>{
    const result=groupEntries(filtered);
    return result.sort((a,b)=>sort==='available-desc'?b.totals.availableValue.comparedTo(a.totals.availableValue):sort==='available-asc'?a.totals.availableValue.comparedTo(b.totals.availableValue):sort==='critical'?b.totals.critical+b.totals.empty-a.totals.critical-a.totals.empty:a.raw['Nº ATA'].localeCompare(b.raw['Nº ATA']));
  },[filtered,sort]);
  const purchases=useMemo(()=>groupPurchases(filtered).sort((a,b)=>sort==='available-asc'?a.totals.availableValue.comparedTo(b.totals.availableValue):sort==='ata'?a.raw['Nº COMPRA'].localeCompare(b.raw['Nº COMPRA']):sort==='critical'?b.totals.critical+b.totals.empty-a.totals.critical-a.totals.empty:b.totals.availableValue.comparedTo(a.totals.availableValue)),[filtered,sort]);
  const allGroups=useMemo(()=>groupEntries(entries),[entries]);
  const selectedEntries=useMemo(()=>entries.filter(e=>selected.has(e.id)),[entries,selected]);
  const selectedTotal=useMemo(()=>totalize(selectedEntries),[selectedEntries]);
  const uggBalances=useMemo(()=>{
    const map=new Map<string,Entry[]>();for(const e of filtered){const list=map.get(e.raw.UGG)??[];list.push(e);map.set(e.raw.UGG,list);}
    return [...map].map(([id,list])=>({id,name:list[0].raw['NOME UGG'],totals:totalize(list)})).sort((a,b)=>b.totals.availableValue.comparedTo(a.totals.availableValue));
  },[filtered]);
  const suppliers=useMemo(()=>{
    const map=new Map<string,Entry[]>();for(const e of filtered){const list=map.get(e.raw.CNPJ)??[];list.push(e);map.set(e.raw.CNPJ,list);}
    return [...map].map(([cnpj,list])=>({cnpj,name:list[0].raw['NOME CNPJ'],count:list.length,total:totalize(list)})).sort((a,b)=>b.total.availableValue.comparedTo(a.total.availableValue));
  },[filtered]);
  const options=useMemo(()=>{
    const unique=(key:(e:Entry)=>string,label:(e:Entry)=>string):[string,string][]=>[...new Map(entries.map(e=>[key(e),label(e)])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt-BR'));
    return {modality:unique(e=>e.raw.MODALIDADE,e=>e.raw.MODALIDADE),ug:unique(e=>e.raw.UG,e=>`${e.raw.UG} · ${e.raw.SIGLA}`),ugg:unique(e=>e.raw.UGG,e=>`${e.raw['NOME UGG']} · ${e.raw.UGG}`),supplier:unique(e=>e.raw.CNPJ,e=>`${e.raw['NOME CNPJ']} · ${e.raw.CNPJ}`),purchase:unique(purchaseKey,e=>`${e.raw['Nº COMPRA']}/${e.raw['ANO COMPRA']} · ${e.raw['NOME UGG']}`),ata:allGroups.map(g=>[g.key,`${g.raw['Nº ATA']}/${g.raw['ANO ATA']} · ${g.raw['NOME UGG']}`] as [string,string]),role:unique(e=>e.raw.TIPO,e=>e.raw.TIPO),itemType:unique(e=>e.raw['TIPO ITEM'],e=>e.raw['TIPO ITEM'])};
  },[entries,allGroups]);
  const activeFilters=Object.values(filters).filter(Boolean).length;
  const setFilter=(key:keyof Filters,value:string)=>{setFilters(f=>({...f,[key]:value}));setPage(0);};
  const clearFilters=()=>{setFilters({...EMPTY_FILTERS});setPage(0);};
  const toggleItems=(items:Entry[])=>setSelected(prev=>{const next=new Set(prev);const all=items.every(e=>next.has(e.id));for(const e of items)if(all)next.delete(e.id);else next.add(e.id);return next;});
  const navigate=(next:View)=>{if(next==='source'&&!canManage)return;setView(next);setPage(0);setMobileNav(false);};
  const readFile=async(file?:File)=>{if(!canManage||!file)return;setBusy('parse');setError('');setPending(null);setImportOpen(true);try{setPending(await parseUpload(file));}catch(e){setError(e instanceof Error?e.message:'Falha ao ler a planilha.');}finally{setBusy('');if(fileInput.current)fileInput.current.value='';}};
  const importDataset=async(target:'local'|'supabase')=>{
    if(!canManage||!pending)return;setBusy('import');setError('');
    try{
      let nextVersion=version;let nextDataset=pending;
      if(target==='supabase'){const response=await fetch('/api/dataset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset:pending,baseVersion:version})});const body=await response.json();if(!response.ok)throw new Error(body.error ?? 'Falha na sincronização.');nextVersion=body.version;nextDataset={...pending,importedAt:body.importedAt};localStorage.removeItem(LOCAL_KEY);}
      else localStorage.setItem(LOCAL_KEY,JSON.stringify({dataset:pending,version}));
      setDataset(nextDataset);setStorage(target);setVersion(nextVersion);setSelected(new Set());setExpanded(new Set());clearFilters();setPending(null);setImportOpen(false);setToast(target==='supabase'?'Planilha importada e sincronizada com o Supabase.':'Planilha salva neste navegador.');
    }catch(e){setError(e instanceof Error?e.message:'Não foi possível importar.');}finally{setBusy('');}
  };
  const doExport=async(kind:'selected'|'filter'|'pdf')=>{
    if(!dataset)return;setBusy(kind);setError('');
    try{const exp=await import('@/lib/export');if(kind==='pdf')await exp.exportPDF(selectedEntries.length?selectedEntries:filtered,dataset,filters,selectedEntries.length?'Itens selecionados':'Filtro atual');else await exp.exportExcel(kind==='selected'?selectedEntries:filtered,dataset,filters,kind==='selected'?'Selecionados':'Filtro atual');setToast(kind==='pdf'?'Relatório PDF gerado.':'Planilha Excel gerada.');}catch(e){setError(e instanceof Error?e.message:'Falha ao gerar arquivo.');}finally{setBusy('');}
  };
  const mainTitle:Record<View,string>={overview:'Visão geral',atas:'Atas e itens',purchases:'Pregões',suppliers:'Fornecedores',source:'Central de dados'};
  const noData=!loading&&!dataset;
  const financialAvailable=totals.financialPercent===null?null:100-totals.financialPercent;
  const pendingTotal=useMemo(()=>pending?totalize(toEntries(pending)):null,[pending]);
  const pageCount=Math.ceil((view==='suppliers'?suppliers.length:view==='purchases'?purchases.length:groups.length)/PAGE_SIZE);

  return <div className="app-shell"><aside className={`sidebar ${mobileNav?'mobile-open':''}`}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('overview');}} aria-label="ARP início"><span className="brand-mark intendencia-mark"><AcantoMark/></span><span>ARP<span className="brand-period">.</span><small>INTELIGÊNCIA EM GESTÃO</small></span></a><div className="workspace-label">AMBIENTE DE TRABALHO</div><nav aria-label="Navegação principal">{([{id:'overview',label:'Visão geral',icon:LayoutDashboard},{id:'purchases',label:'Pregões',icon:FolderOpen},{id:'atas',label:'Atas e itens',icon:Layers3},{id:'suppliers',label:'Fornecedores',icon:Users},{id:'source',label:'Central de dados',icon:Database}] as const).filter(item=>canManage||item.id!=='source').map(item=><button key={item.id} className={`nav-item ${view===item.id?'active':''}`} onClick={()=>navigate(item.id)}><item.icon size={18}/><span>{item.label}</span>{view===item.id&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-base"><div className="side-note"><div className="side-note-icon"><ShieldCheck size={19}/></div><strong>Dados que orientam decisões.</strong><p>Visibilidade do saldo, do item ao panorama executivo.</p><button onClick={()=>setMethodOpen(true)}>Entenda os cálculos<ArrowUpRight size={14}/></button></div><button className="help-link" onClick={()=>{setHelpStep(0);setHelpOpen(true);}}><CircleHelp size={19}/>Como usar · Ajuda</button><button className="help-link" onClick={onLogout}>Sair · {canManage?'Administrador':'Consulta'}</button><div className="workspace-card"><div className="workspace-avatar">{entries[0]?.raw.SIGLA?.split(' ')[0] ?? 'UG'}</div><div className="min-w-0"><strong title={entries[0]?.raw.SIGLA}>{entries[0]?.raw.SIGLA ?? 'Gestão de ARP'}</strong><span>UG {entries[0]?.raw.UG ?? '—'}</span></div><span className={`connection-dot ${storage==='supabase'?'online':''}`} title={storage==='supabase'?'Supabase conectado':'Base local'}/></div></div></aside>{mobileNav&&<button className="mobile-scrim" onClick={()=>setMobileNav(false)} aria-label="Fechar navegação"/>}<div className="main-shell"><header className="topbar"><div className="flex items-center gap-3 min-w-0"><button className="icon-button mobile-menu" onClick={()=>setMobileNav(v=>!v)} aria-label="Abrir navegação"><Menu size={21}/></button><span className="breadcrumb">Gestão de contratações</span><ChevronRight size={13} className="muted"/><span className="topbar-current">{mainTitle[view]}</span></div><div className="topbar-right"><span className={`connection-label ${storage==='supabase'?'connected':''}`}>{storage==='supabase'?<Cloud size={14}/>:<HardDrive size={14}/>}<span>{loading?'Carregando base':storage==='supabase'?'Supabase conectado':'Armazenamento local'}</span></span><button className="icon-button" onClick={()=>void load()} disabled={loading} title="Atualizar dados" aria-label="Atualizar dados"><RefreshCw size={16} className={loading?'animate-spin':''}/></button><span className="topbar-separator"/><button className="top-avatar" disabled={!canManage} onClick={()=>navigate('source')} title={canManage?'Ver arquivo de origem':'Acesso de consulta'}>UG</button></div></header><main className="main-content"><section className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line"/>PAINEL EXECUTIVO</div><h1>{view==='overview'?<>Cada saldo.<br className="mobile-break"/> Uma decisão.</>:mainTitle[view]}</h1><p>{view==='overview'?'Seus pregões e atas de registro de preços, em uma única visão.':view==='purchases'?'Explore os pregões, seus objetos oficiais, atas e itens.':view==='atas'?'Consulte os saldos, selecione itens e explore cada ata.':view==='suppliers'?'Saldo disponível e participação por fornecedor.':'Importação, origem e integridade da sua base.'}</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>void doExport('pdf')} disabled={!filtered.length||!!busy}><FileDown size={16}/>{busy==='pdf'?'Gerando…':'Relatório PDF'}</button>{canManage&&<button className="button primary" onClick={()=>{setImportOpen(true);setError('');}}><Upload size={16}/>Importar planilha</button>}<button className="button secondary" onClick={()=>{setHelpStep(0);setHelpOpen(true);}}><CircleHelp size={17}/>Como usar</button></div></section>{error&&<div className="notice warning" role="alert"><TriangleAlert size={18}/><span>{error}</span><button onClick={()=>setError('')} className="icon-button" aria-label="Dispensar erro"><X size={16}/></button></div>}{canManage&&storage==='local'&&dataset&&<div className="notice local-note"><HardDrive size={17}/><span>Modo local: esta visão usa uma cópia da planilha. {version>0?'A sincronização com o Supabase não foi aplicada a esta cópia.':'O modo local está ativo.'}</span>{version>0&&<button className="text-button" onClick={()=>{localStorage.removeItem(LOCAL_KEY);void load(false);}}>Carregar Supabase</button>}</div>}{loading&&!dataset?<div className="loading-state"><LoaderCircle className="animate-spin" size={28}/><h2>Conferindo sua base</h2><p>Carregando os dados reais da planilha.</p></div>:noData?<div className="empty-state"><Database size={34}/><h2>A base não pôde ser carregada</h2><p>Tente novamente ou importe uma planilha com as 26 colunas.</p><button className="button primary" onClick={()=>void load(false)}>Tentar novamente</button></div>:<>
  {view!=='source'&&<><div className="context-strip"><div className="flex flex-wrap items-center gap-x-4 gap-y-2"><span className="context-ug"><Building2 size={14}/>{entries[0]?.raw.SIGLA} · UG {entries[0]?.raw.UG}</span><span className="context-divider"/><span>{number(new Set(filtered.map(purchaseKey)).size)} compras</span><span>{number(groups.length)} atas</span><span>{number(filtered.length)} itens</span></div><button className="source-chip" disabled={!canManage} title={dataset?.filename} onClick={()=>navigate('source')}><FileSpreadsheet size={13}/><span>{dataset?.filename}</span><ArrowUpRight size={12}/></button></div>{view==='overview'&&<section className="kpi-grid" aria-label="Indicadores financeiros"><article className="kpi-card"><div className="kpi-label">Total homologado<Layers3 size={18}/></div><strong className="kpi-value" title={money(totals.approvedValue)}>{money(totals.approvedValue)}</strong><div className="kpi-foot"><span className="dot slate"/>Base das atas {activeFilters?'filtradas':'importadas'}</div></article><article className="kpi-card"><div className="kpi-label">Consumo calculado<Activity size={18}/></div><strong className="kpi-value" title={money(totals.usedValue)}>{money(totals.usedValue)}</strong><div className="kpi-foot"><span className="tiny-pill">{percent(totals.financialPercent)}</span><span>do valor homologado</span><button onClick={()=>setMethodOpen(true)} aria-label="Como o consumo é calculado" className="inline-help"><Info size={12}/></button></div></article><article className="kpi-card highlighted"><div className="kpi-label">Saldo disponível<Wallet size={19}/></div><strong className="kpi-value accent" title={money(totals.availableValue)}>{money(totals.availableValue)}</strong><div className="kpi-foot"><span className="dot lime"/>{percent(financialAvailable)} do valor homologado</div></article><article className="kpi-card critical-card"><div className="kpi-label">Itens que exigem atenção<TriangleAlert size={18}/></div><strong className="kpi-value">{number(totals.critical+totals.empty+totals.invalid)}<span className="kpi-unit">itens</span></strong><div className="kpi-foot"><span className="critical-dot"/>{number(totals.critical)} críticos<span className="muted">·</span>{number(totals.empty)} esgotados{totals.invalid>0?` · ${number(totals.invalid)} a revisar`:''}</div></article></section>}
  <section className="filter-panel" aria-label="Filtros da base"><AcantoMark className="filter-acanto"/><div className="filter-intro"><span className="filter-intro-icon"><SlidersHorizontal size={24}/></span><div><h2>Encontre o que você precisa</h2><p>Digite o item ou combine os filtros abaixo para refinar os resultados.</p></div></div><div className="search-row"><label className="global-search"><Search size={18}/><input ref={searchRef} placeholder="Busque por item, descrição, ata, pregão ou fornecedor…" value={filters.query} onChange={e=>setFilter('query',e.target.value)} aria-label="Busca global"/><kbd>Ctrl K</kbd>{filters.query&&<button onClick={()=>setFilter('query','')} aria-label="Limpar busca"><X size={14}/></button>}</label><button className={`button filter-toggle ${advanced?'enabled':''}`} onClick={()=>setAdvanced(v=>!v)} aria-expanded={advanced}><SlidersHorizontal size={16}/>Mais filtros{activeFilters>0&&<span className="filter-count">{activeFilters}</span>}<ChevronDown size={14}/></button>{activeFilters>0&&<button className="text-button clear-filters" onClick={clearFilters}>Limpar filtros<X size={13}/></button>}</div><div className="filter-grid"><Select label="Modalidade" value={filters.modality} onChange={v=>setFilter('modality',v)} options={options.modality} all="Todas as modalidades"/><Select label="Gerenciadora / UGG" value={filters.ugg} onChange={v=>setFilter('ugg',v)} options={options.ugg} all="Todas as gerenciadoras"/><Select label="Fornecedor / CNPJ" value={filters.supplier} onChange={v=>setFilter('supplier',v)} options={options.supplier} all="Todos os fornecedores"/><Select emphasis label="Saldo disponível" value={filters.status} onChange={v=>setFilter('status',v)} options={(['Normal','Crítico','Esgotado','Revisar'] as const).map(s=>[s,s==='Crítico'?'Crítico · saldo < 15%':s])} all="Todos os saldos"/></div>{advanced&&<div className="advanced-grid"><Select label="Compra / pregão" value={filters.purchase} onChange={v=>setFilter('purchase',v)} options={options.purchase}/><Select label="Ata / ano" value={filters.ata} onChange={v=>setFilter('ata',v)} options={options.ata}/><Select label="UG participante" value={filters.ug} onChange={v=>setFilter('ug',v)} options={options.ug}/><Select label="Vigência da ata" value={filters.validity} onChange={v=>setFilter('validity',v)} options={ [['vigente','Vigentes hoje'],['expirada','Vencidas'],['futura','Vigência futura']] }/><Select label="Participação" value={filters.role} onChange={v=>setFilter('role',v)} options={options.role}/><Select label="Tipo de item" value={filters.itemType} onChange={v=>setFilter('itemType',v)} options={options.itemType}/></div>}</section>
  {view==='overview'&&<section className="charts-grid"><article className="chart-card balance-chart"><div className="section-heading"><div><h2>Panorama do saldo</h2><p>Distribuição do valor homologado</p></div><span className="small-pill">Financeiro</span></div><div className="balance-chart-body"><div className="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label={`${percent(financialAvailable)} do valor homologado disponível`}><circle cx="90" cy="90" r="72" fill="none" stroke="#283246" strokeWidth="15"/><circle cx="90" cy="90" r="72" fill="none" stroke="var(--accent)" strokeWidth="15" strokeDasharray={`${clampPercent(financialAvailable)/100*452.389} 452.389`} strokeLinecap="round" transform="rotate(-90 90 90)"/></svg><div className="donut-center"><span>DISPONÍVEL</span><strong title={percent(financialAvailable)}>{financialAvailable===null?'—':percent(financialAvailable)}</strong><small>do valor homologado</small></div></div><div className="donut-legend"><div><span className="dot lime"/><span>Disponível<strong>{money(totals.availableValue)}</strong></span></div><div><span className="dot slate"/><span>Consumo calculado<strong>{money(totals.usedValue)}</strong></span></div><button className="chart-method" onClick={()=>setMethodOpen(true)}>Ver metodologia<ArrowUpRight size={13}/></button></div></div><div className="status-distribution"><div className="distribution-label"><span>Situação dos itens</span><span>{number(filtered.length)} no filtro</span></div><div className="distribution-bar" role="img" aria-label={`${totals.normal} normais, ${totals.critical} críticos e ${totals.empty} esgotados`}>{totals.normal>0&&<span style={{width:`${totals.normal/filtered.length*100}%`}} className="normal"/>}{totals.critical>0&&<span style={{width:`${totals.critical/filtered.length*100}%`}} className="critical"/>}{totals.empty>0&&<span style={{width:`${totals.empty/filtered.length*100}%`}} className="empty"/>}{totals.invalid>0&&<span style={{width:`${totals.invalid/filtered.length*100}%`}} className="review"/>}</div><div className="distribution-legend"><button onClick={()=>setFilter('status',filters.status==='Normal'?'':'Normal')}><i className="normal"/>Normal <b>{number(totals.normal)}</b></button><button onClick={()=>setFilter('status',filters.status==='Crítico'?'':'Crítico')}><i className="critical"/>Crítico <b>{number(totals.critical)}</b></button><button onClick={()=>setFilter('status',filters.status==='Esgotado'?'':'Esgotado')}><i className="empty"/>Esgotado <b>{number(totals.empty)}</b></button></div></div></article><article className="chart-card ugg-chart"><div className="section-heading"><div><h2>Saldo por gerenciadora</h2><p>As maiores disponibilidades do filtro atual</p></div><Building2 size={19} className="muted"/></div><div className="bar-chart">{uggBalances.slice(0,5).map((g,i)=><button key={g.id} className="bar-chart-row" onClick={()=>setFilter('ugg',filters.ugg===g.id?'':g.id)} title={`Filtrar ${g.name} · ${money(g.totals.availableValue)}`}><div className="bar-row-label"><span><small>{String(i+1).padStart(2,'0')}</small><b>{g.name}</b></span><strong>{money(g.totals.availableValue)}</strong></div><div className="bar-track"><span style={{width:`${uggBalances[0]?.totals.availableValue.gt(0)?g.totals.availableValue.div(uggBalances[0].totals.availableValue).times(100).toNumber():0}%`,opacity:1-i*.12}}/></div></button>)}{!uggBalances.length&&<p className="muted">Nenhum saldo neste filtro.</p>}</div><div className="chart-bottom"><span>{uggBalances.length} gerenciadoras no filtro</span><button onClick={()=>{setAdvanced(true);searchRef.current?.focus();}}>Explorar base<ArrowUpRight size={13}/></button></div></article></section>}
  {view==='suppliers'?<section className="results-section"><div className="results-heading"><div><h2>Fornecedores<span className="count-pill">{suppliers.length}</span></h2><p>Ordenados pelo saldo disponível em reais.</p></div><button className="button secondary" disabled={!filtered.length||!!busy} onClick={()=>void doExport('filter')}><Download size={15}/>Exportar filtro (.xlsx)</button></div><div className="supplier-grid">{suppliers.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE).map(s=><button className="supplier-card" key={s.cnpj} onClick={()=>{setFilter('supplier',s.cnpj);navigate('atas');}}><div className="supplier-icon"><Building2 size={21}/></div><h3 title={s.name}>{s.name}</h3><p>{s.cnpj}</p><div><span>{number(s.count)} itens</span><ArrowUpRight size={15}/></div><strong>{money(s.total.availableValue)}</strong><small>saldo disponível</small></button>)}</div></section>:<section className="results-section" id="atas"><div className="results-heading"><div><h2>{view==='purchases'?'Pregões':'Atas de registro de preços'}<span className="count-pill">{number(view==='purchases'?purchases.length:groups.length)}</span></h2><p>{activeFilters?'Exibindo os itens que correspondem aos filtros.':'Do panorama ao detalhe: acompanhe cada ata e seus itens.'}</p></div><div className="results-actions">{view!=='purchases'&&<button className="text-button" onClick={()=>{const visible=groups.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE);const all=visible.every(g=>expanded.has(g.key));setExpanded(prev=>{const next=new Set(prev);for(const g of visible)if(all)next.delete(g.key);else next.add(g.key);return next;});}}>{groups.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE).every(g=>expanded.has(g.key))?'Recolher página':'Expandir página'}<ChevronDown size={13}/></button>}<label className="sort-label"><span className="sr-only">Ordenação das atas</span><select value={sort} onChange={e=>{setSort(e.target.value);setPage(0);}}><option value="available-desc">Maior saldo</option><option value="available-asc">Menor saldo</option><option value="critical">Mais itens em atenção</option><option value="ata">Número da ata</option></select><ChevronDown size={13}/></label></div></div><div className="selection-toolbar"><div className="selection-info"><Checkbox checked={filtered.length>0&&filtered.every(e=>selected.has(e.id))} mixed={filtered.some(e=>selected.has(e.id))} label="Selecionar todos os itens do filtro, incluindo outras páginas" onChange={()=>toggleItems(filtered)}/><span>{selected.size?`${number(selected.size)} itens selecionados`:'Selecionar todos os itens do filtro'}</span>{selected.size>0&&<button className="text-button" onClick={()=>setSelected(new Set())}>Limpar</button>}</div><div className="export-actions"><button className="button export-button" disabled={!selected.size||!!busy} onClick={()=>void doExport('selected')}><ArrowDownToLine size={14}/>{busy==='selected'?'Exportando…':'Exportar selecionados (.xlsx)'}</button><button className="button export-button" disabled={!filtered.length||!!busy} onClick={()=>void doExport('filter')}><Download size={14}/>{busy==='filter'?'Exportando…':'Exportar filtro atual (.xlsx)'}</button></div></div>{selected.size>0&&<div className="selection-detail"><Check size={14}/><span>Saldo dos selecionados: <strong>{money(selectedTotal.availableValue)}</strong></span><span>{selectedEntries.filter(e=>!filtered.some(f=>f.id===e.id)).length} selecionados fora do filtro atual. O PDF usa a seleção enquanto ela estiver ativa.</span></div>}<div className="atas-list">{view==='purchases'?purchases.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE).map(purchase=><PurchaseCard key={purchase.key} purchase={purchase} selected={selected} toggleItems={toggleItems} onDetail={setDetail} expanded={expanded} toggleAta={key=>setExpanded(prev=>{const next=new Set(prev);if(next.has(key))next.delete(key);else next.add(key);return next;})}/>):groups.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE).map(group=><AtaCard key={group.key} group={group} selected={selected} toggleItems={toggleItems} onDetail={setDetail} open={expanded.has(group.key)} onToggle={()=>setExpanded(prev=>{const next=new Set(prev);if(next.has(group.key))next.delete(group.key);else next.add(group.key);return next;})}/>)}</div>{!groups.length&&<div className="empty-state"><Search size={30}/><h3>Nenhum item encontrado</h3><p>Experimente outro termo ou limpe os filtros.</p><button className="button secondary" onClick={clearFilters}>Limpar filtros</button></div>}</section>}{pageCount>0&&<div className="pagination main-pagination"><span>{view==='suppliers'?'Fornecedores':view==='purchases'?'Pregões':'Atas'} {page*PAGE_SIZE+1}–{Math.min((page+1)*PAGE_SIZE,view==='suppliers'?suppliers.length:view==='purchases'?purchases.length:groups.length)} de {view==='suppliers'?suppliers.length:view==='purchases'?purchases.length:groups.length}</span><div><button className="icon-button" disabled={page===0} onClick={()=>setPage(p=>p-1)} aria-label="Página anterior"><ArrowLeft size={16}/></button><span>Página {page+1} de {pageCount}</span><button className="icon-button" disabled={page+1>=pageCount} onClick={()=>setPage(p=>p+1)} aria-label="Próxima página"><ArrowRight size={16}/></button></div></div>}<div className="methodology-inline"><Info size={14}/><p>Consumo calculado por diferença entre quantidade homologada e disponível. O saldo inclui atas vencidas se não houver filtro de vigência.</p><button onClick={()=>setMethodOpen(true)}>Metodologia<ArrowUpRight size={12}/></button></div></>}
  {view==='source'&&canManage&&<><Members/><div className="source-layout"><article className="chart-card source-card"><div className="source-file-icon"><FileSpreadsheet size={31}/></div><div className="eyebrow">ARQUIVO EM USO</div><h2>{dataset?.filename}</h2><p>Dados reais da planilha importada. As células originais permanecem disponíveis no detalhamento e nas exportações.</p><dl className="source-facts"><div><dt>Itens</dt><dd>{number(entries.length)}</dd></div><div><dt>Colunas mapeadas</dt><dd>{HEADERS.length} / {HEADERS.length}</dd></div><div><dt>Atas</dt><dd>{number(allGroups.length)}</dd></div><div><dt>Destino</dt><dd>{storage==='supabase'?'Supabase':'Este navegador'}</dd></div><div><dt>Versão de sincronização</dt><dd>{version||'Sem sincronização'}</dd></div><div><dt>Importado em</dt><dd>{dataset?.importedAt?new Date(dataset.importedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Não informado'}</dd></div></dl><div className="source-hash"><span>SHA-256 DO ARQUIVO</span><code>{dataset?.contentHash}</code></div></article><button className={`dropzone source-dropzone ${drag?'dragging':''}`} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);void readFile(e.dataTransfer.files[0]);}} onClick={()=>{setImportOpen(true);fileInput.current?.click();}}><span className="upload-symbol"><Upload size={29}/></span><h3>Atualize sua visão.</h3><p>Arraste sua planilha para cá<br/>ou clique para selecionar um arquivo.</p><span className="button primary">Selecionar planilha<ArrowUpRight size={15}/></span><small>.XLSX, .XLS ou .CSV · até 20 MB</small></button></div><section className="chart-card mapped-columns"><div className="section-heading"><div><h2>Mapeamento fiel à origem</h2><p>Os 26 cabeçalhos exigidos estão presentes na base.</p></div><span className="status normal"><Check size={13}/>26 colunas</span></div><div className="columns-grid">{HEADERS.map((h,i)=><div key={h}><span>{String(i+1).padStart(2,'0')}</span><strong>{h}</strong><Check size={13}/></div>)}</div></section><div className="notice"><ShieldCheck size={19}/><span>Sincronização por conexão de servidor. O banco não permite acesso público às tabelas. Importações preservam versões anteriores e detectam conflitos entre sessões.</span></div></>}
  </>}<footer className="footer"><span><Layers3 size={14}/>ARP<span className="muted">/</span>Gestão de pregões e saldos</span><span>Precisão para decidir.</span></footer></main></div>
  <input type="file" ref={fileInput} accept=".xlsx,.xls,.csv" className="sr-only" tabIndex={-1} aria-label="Arquivo de planilha" onChange={e=>void readFile(e.target.files?.[0])}/>
  {toast&&<div className="toast" role="status"><Check size={17}/>{toast}<button onClick={()=>setToast('')} aria-label="Fechar aviso"><X size={14}/></button></div>}
  {detail&&<ItemDetail entry={detail} onClose={()=>setDetail(null)}/>}
  {helpOpen&&<Modal title="Como usar o dashboard" subtitle={`Passo ${helpStep+1} de 6 · Guia rápido`} onClose={()=>setHelpOpen(false)} wide><div className="tutorial-step"><span className="tutorial-number">{String(helpStep+1).padStart(2,'0')}</span><h3>{['Comece pela visão geral','Encontre o que você precisa','Explore pregões, atas e itens','Selecione e exporte','Leia o saldo com segurança','Compartilhe e mantenha a base'][helpStep]}</h3><p>{['Os indicadores mostram o valor homologado, o consumo calculado e o saldo disponível. Todos acompanham os filtros que você aplicar.','Digite descrição, número ou fornecedor na busca. Combine modalidade, UGG, CNPJ e status. Em Mais filtros, escolha pregão, ata e vigência. Limpar filtros restaura a base completa.','Na aba Pregões, abra a seta para ver as atas daquele pregão. Abra outra seta para ver os itens. Clique na descrição ou na lupa para consultar as 26 colunas. O objeto é consultado no PNCP, com identificação da fonte.','Marque itens, atas ou um pregão inteiro. Exportar selecionados usa sua seleção; Exportar filtro atual usa todos os resultados do filtro. O PDF usa a seleção enquanto houver itens marcados. Confira os selecionados fora do filtro.','Crítico significa saldo positivo menor que 15%; esgotado significa zero. Consumo calculado é homologada menos disponível, sem comprovar empenhos emitidos. Para comprar, confira também a vigência e a situação no sistema oficial.','Quem tem acesso de consulta pode explorar e exportar, mas não importar nem trocar a base. O administrador usa a Central de dados para importar a planilha completa, conferir a prévia e sincronizar. Também pode gerar convites pessoais e revogar acessos.'][helpStep]}</p></div><div className="tutorial-controls"><button className="button secondary" disabled={helpStep===0} onClick={()=>setHelpStep(s=>s-1)}>Anterior</button><span>{helpStep+1} / 6</span><button className="button primary" onClick={()=>helpStep===5?setHelpOpen(false):setHelpStep(s=>s+1)}>{helpStep===5?'Concluir':'Próximo'}</button></div><h3 className="mt-6 mb-3 font-semibold">Dúvidas frequentes</h3><div className="faq-list"><details><summary>Por que o link antigo do item não abre?</summary><p>Alguns links de transparência da planilha retornam 404. O botão Itens no PNCP abre a compra oficial; localize ali o número do item. Na aba Pregões, o botão Compra no Compras.gov usa o endereço oficial informado pelo PNCP.</p></details><details><summary>As informações são atualizadas em tempo real?</summary><p>Os saldos refletem a última planilha sincronizada pelo administrador. O objeto vem do PNCP e pode ficar em cache por até 24 horas. Atualizar a página não consulta novos saldos no Compras.gov.</p></details><details><summary>Posso alterar dados ao filtrar ou exportar?</summary><p>Não. Filtros, seleção e exportação só mudam sua consulta. Somente a importação administrativa substitui a base ativa.</p></details><details><summary>Como liberar acesso para outra pessoa?</summary><p>O administrador abre a Central de dados, informa o e-mail e gera um convite. Copia o link pessoal e envia à pessoa, que cria a própria senha. O convite é de uso único e expira em 24 horas.</p></details></div><button className="text-button mt-5" onClick={()=>{setHelpOpen(false);setMethodOpen(true);}}>Ver fórmulas e metodologia</button></Modal>}
{methodOpen&&<Modal title="Transparência nos cálculos" subtitle="A mesma regra, do item ao panorama executivo." onClose={()=>setMethodOpen(false)} wide><div className="notice"><Info size={19}/><span>{METHODOLOGY}</span></div><div className="formula-list"><div><span>Quantidade consumida calculada</span><code>QTD HOMOLOGADA − QTD DISPONÍVEL</code></div><div><span>Valor total homologado</span><code>QTD HOMOLOGADA × VALOR UNITÁRIO</code></div><div><span>Valor consumido calculado</span><code>(HOMOLOGADA − DISPONÍVEL) × VALOR UNITÁRIO</code></div><div><span>Valor disponível</span><code>QTD DISPONÍVEL × VALOR UNITÁRIO</code></div><div><span>Consumo quantitativo</span><code>(CONSUMIDA ÷ HOMOLOGADA) × 100</code></div><div><span>Consumo financeiro agregado</span><code>(Σ VALOR CONSUMIDO ÷ Σ VALOR HOMOLOGADO) × 100</code></div></div><h3 className="mt-6 mb-3 font-semibold">Como interpretar</h3><ul className="help-list"><li><strong>Crítico:</strong> disponível maior que zero e menor que 15% da quantidade homologada. Saldo exatamente em 15% é normal.</li><li><strong>Esgotado:</strong> quantidade disponível igual a zero. Divisão por homologada igual a zero é exibida como não aplicável.</li><li><strong>Agrupamento:</strong> UG + UGG + nome da gerenciadora + número e ano da ata, preservando os zeros dos identificadores. Atas do mesmo pregão permanecem separadas.</li><li><strong>Escopo:</strong> os indicadores e gráficos seguem o filtro atual. Seleções podem incluir outras páginas e filtros; o total selecionado é informado antes da exportação.</li><li><strong>Quantidades:</strong> totais de itens distintos podem misturar unidades. O panorama e o consumo das atas usam a ponderação financeira; a exportação também inclui o percentual quantitativo.</li><li><strong>Vigência:</strong> saldo positivo não comprova que uma ata está vigente. Use o filtro de vigência para restringir às atas vigentes hoje, no fuso de Brasília.</li><li><strong>Precisão:</strong> valores calculados com aritmética decimal e apresentados em reais. Células vazias não são convertidas em zero; dados inconsistentes são sinalizados.</li></ul></Modal>}
  {importOpen&&canManage&&<Modal title="Importar planilha" subtitle="Valide a base antes de atualizar o dashboard." onClose={()=>{if(!busy){setImportOpen(false);setPending(null);}}} wide>{error&&<div className="notice warning" role="alert"><TriangleAlert size={18}/><span>{error}</span></div>}{busy==='parse'?<div className="loading-state"><LoaderCircle size={26} className="animate-spin"/><h3>Validando as 26 colunas</h3><p>Números, datas e links estão sendo conferidos.</p></div>:pending&&pendingTotal?<><div className="import-file"><FileSpreadsheet size={24}/><div><strong>{pending.filename}</strong><p>{number(pending.rows.length)} itens · 26 colunas · {groupEntries(toEntries(pending)).length} atas</p></div><span className="status normal"><Check size={13}/>Validada</span></div><div className="detail-metrics"><div><span>Total homologado</span><strong>{money(pendingTotal.approvedValue)}</strong></div><div><span>Saldo disponível</span><strong className="accent">{money(pendingTotal.availableValue)}</strong></div><div><span>Itens críticos / esgotados</span><strong>{number(pendingTotal.critical)} / {number(pendingTotal.empty)}</strong></div></div>{pendingTotal.invalid>0&&<div className="notice warning"><TriangleAlert size={18}/>{pendingTotal.invalid} itens têm inconsistências e serão identificados como “Revisar”. Nenhum valor será corrigido automaticamente.</div>}<div className="notice"><Info size={18}/><span>A importação substitui a base ativa inteira. A sincronização preserva o snapshot anterior no Supabase. Confira se o arquivo contém a base completa desejada.</span></div><div className="import-actions"><button className="button secondary" disabled={!!busy} onClick={()=>setPending(null)}>Escolher outro arquivo</button><button className="button secondary" disabled={!!busy} onClick={()=>void importDataset('local')}><HardDrive size={16}/>Salvar no navegador</button><button className="button primary" disabled={!!busy} onClick={()=>void importDataset('supabase')}>{busy==='import'?<LoaderCircle className="animate-spin" size={16}/>:<Cloud size={16}/>}Importar e sincronizar</button></div></>:<button className={`dropzone ${drag?'dragging':''}`} disabled={!!busy} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);void readFile(e.dataTransfer.files[0]);}} onClick={()=>fileInput.current?.click()}><span className="upload-symbol"><Upload size={28}/></span><h3>Arraste sua planilha aqui</h3><p>ou clique para selecionar no computador.</p><small>.XLSX, .XLS ou .CSV · até 20 MB · 26 colunas originais</small></button>}<p className="method-note mt-5">Compatível com a exportação HTML do Compras.gov salva como .xls. A importação mantém os identificadores, os links e os dados originais.</p></Modal>}
  </div>;
}
